cd /app/categorizationapp/categorizationapp && python3 - <<'EOF'
import re,glob,ast
for f in glob.glob('**/*.py', recursive=True):
    src=open(f).read()
    for m in re.finditer(r'py_extract\(([^()]*(?:\([^()]*\))?[^()]*)\)', src):
        call=m.group(0)
        # find pat= and index=
        pm=re.search(r'pat\s*=\s*(".*?"|[A-Z_0-9]+)', call, re.S)
        im=re.search(r'index\s*=\s*(-?\d+)', call)
        if not pm or not im: 
            print("SKIP", f, call[:120]); continue
        pat=pm.group(1); idx=int(im.group(1))
        if pat.startswith('"'):
            p=ast.literal_eval(pat)
        else:
            p=None
        line=src[:m.start()].count('\n')+1
        if p is not None:
            ngroups=re.compile(p).groups
            if idx>=ngroups:
                print(f"{f}:{line} idx={idx} groups={ngroups} pat={p!r}")
        else:
            print(f"{f}:{line} CONST {pat} idx={idx}")
EOF

