enums|=set(re.findall(r'^\s{4}([A-Z][A-Z0-9_]+)=', open('UtilityScripts/TransactionSubcategoryEnums.py').read(), re.M))
for f in sorted(glob.glob('BankScripts/*.py'))+sorted(glob.glob('UtilityScripts/*.py')):
    src=open(f).read()
    for i,line in enumerate(src.split('\n'),1):
        # candidate choice strings at end: , "XXX"]
        for m in re.finditer(r'[,\s]"([A-Z][A-Z0-9_]{3,})"\s*\]', line):
            s=m.group(1)
            if s not in enums and s not in ("DEBIT","CREDIT","SAVING","CURRENT","CREDIT_CARD","OVER_DRAFT"):
                print(f"{f}:{i}: {s}")
