cat > /tmp/opencode/regress2.py <<'EOF'
exec(open('/tmp/opencode/regress.py').read().split('COLS =')[0])
COLS = ['transactionCategory','transactionSubcategory','partyName']
import collections
for bank,(module,fn) in BANKS.items():
    for at in ACCT:
        old = getattr(load("/tmp/opencode/pristine/categorizationapp", module), fn)(base.copy(), at)
        new = getattr(load("/app/categorizationapp", module), fn)(base.copy(), at)
        cols = [c for c in COLS if c in old.columns and c in new.columns]
        o = old[cols].astype(str); n = new[cols].astype(str)
        mask = (o != n).any(axis=1)
        if not mask.any():
            print(f"{bank}/{at}: no change"); continue
        cnt = collections.Counter()
        for i in base.index[mask]:
            key = []
            for c in cols:
                if o.at[i,c] != n.at[i,c]:
                    key.append(f"{c}: {o.at[i,c]!r} -> {n.at[i,c]!r}")
            trig = []
            import re
            if re.fullmatch(r'[0-9]{6}', base.at[i,'remark'] or ''): trig.append("remark=6digits")
            if 'MANDATE' in base.at[i,'description'].upper(): trig.append("mandate")
            if 'POS TXN' in base.at[i,'description'].upper(): trig.append("postxn")
            if 'NACH-' in base.at[i,'description'].upper(): trig.append("nach")
            cnt[(tuple(key), tuple(trig), base.at[i,'type'], base.at[i,'amount'] if base.at[i,'amount']<=2 else '>2')]+=1
        print(f"\n### {bank}/{at}: {int(mask.sum())} rows changed, {len(cnt)} distinct change-kinds")
        for k,v in sorted(cnt.items(), key=lambda x:-x[1]):
            print("   ", v, k)
EOF
